class TestCompanionServer {
 const string Origin="https://192.168.1.20:38473";static readonly JavaScriptSerializer Json=new JavaScriptSerializer();static int checks;
 static void Check(bool condition,string message){if(!condition)throw new Exception(message);checks++;Console.WriteLine("PASS "+message);}
 static Dictionary<string,object> Data(CompanionReply reply){return Json.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(reply.Body));}
 static CompanionRequest Request(string path,string method,object body,string cookie,string csrf){return new CompanionRequest{Path=path,Method=method,Origin=Origin,ContentType="application/json",Body=body==null?"":Json.Serialize(body),Cookie=cookie,Csrf=csrf,RemoteAddress="192.168.1.21"};}
 static CompanionReply Call(CompanionServer server,string path,string method,object body,string cookie,string csrf){return server.Dispatch(Request(path,method,body,cookie,csrf),Origin);}
 static Dictionary<string,object> Status(CompanionServer server){return Json.Deserialize<Dictionary<string,object>>(Json.Serialize(server.Status()));}
 static string OpenTestPairing(CompanionServer server){return (string)typeof(CompanionServer).GetMethod("CreatePairingWindow",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(server,null);}
 static object PendingTicket(CompanionServer server,string ticket){var entries=(System.Collections.IDictionary)typeof(CompanionServer).GetField("pending",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(server);foreach(object item in entries.Values)if((string)item.GetType().GetField("ticket").GetValue(item)==ticket)return item;throw new Exception("Expected pending ticket");}
 static string PendingId(object ticket){return (string)ticket.GetType().GetField("id").GetValue(ticket);}
 static DateTime PendingExpiry(object ticket){return (DateTime)ticket.GetType().GetField("expiresAt").GetValue(ticket);}
 static void SetExpiry(object ticket,DateTime value){ticket.GetType().GetField("expiresAt").SetValue(ticket,value);}
 static string SubmitPair(CompanionServer server,string code,string name){var response=Call(server,"/api/pair","POST",new{code=code,name=name},null,null);if(response.Status!=202)throw new Exception("Pair setup failed: "+response.Status);return (string)Data(response)["ticket"];}
 static void PairingLifetimeChecks(string fixture){
  string root=Path.Combine(fixture,"pairing-lifetimes");Directory.CreateDirectory(root);
  using(var server=new CompanionServer(root,(path,body,grant)=>CompanionReply.Json(200,new{ok=true}),()=>false)){
   string oldCode=OpenTestPairing(server),waiting=SubmitPair(server,oldCode,"Waiting iPad");object waitingItem=PendingTicket(server,waiting);DateTime originalExpiry=PendingExpiry(waitingItem);
   string newCode=OpenTestPairing(server);Check(newCode!=oldCode,"regenerating always rotates the six-digit entry code");Check(Call(server,"/api/pair","POST",new{ticket=waiting},null,null).Status==202&&PendingExpiry(waitingItem)==originalExpiry,"regeneration preserves an already accepted unapproved request and its deadline");
   Check(Call(server,"/api/pair","POST",new{code=oldCode,name="Old code iPad"},null,null).Status==401,"old entry code cannot create a new request after regeneration");
   string approved=SubmitPair(server,newCode,"Approved iPad");object approvedItem=PendingTicket(server,approved);DateTime approvedOriginal=PendingExpiry(approvedItem);server.Approve(PendingId(approvedItem),new CompanionGrant());Check(PendingExpiry(approvedItem)==approvedOriginal,"early approval does not shorten the existing claim deadline");
   newCode=OpenTestPairing(server);Check(Call(server,"/api/pair","POST",new{ticket=approved},null,null).Status==200,"regeneration preserves an approved ticket until the browser claims its cookie");
   originalExpiry=DateTime.UtcNow.AddSeconds(1);SetExpiry(waitingItem,originalExpiry);DateTime approvingAt=DateTime.UtcNow;server.Approve(PendingId(waitingItem),new CompanionGrant());Check(PendingExpiry(waitingItem)>=approvingAt.AddSeconds(30)&&PendingExpiry(waitingItem)<=DateTime.UtcNow.AddSeconds(30),"near-deadline approval adds a bounded thirty-second claim window");Thread.Sleep(1100);
   Check(DateTime.UtcNow>originalExpiry&&Call(server,"/api/pair","POST",new{ticket=waiting},null,null).Status==200,"approved browser can claim after the original request deadline");
   DateTime submittingAt=DateTime.UtcNow;string expiring=SubmitPair(server,newCode,"Unapproved iPad");object expiringItem=PendingTicket(server,expiring);Check(PendingExpiry(expiringItem)>=submittingAt.AddMinutes(2)&&PendingExpiry(expiringItem)<=DateTime.UtcNow.AddMinutes(2),"unapproved requests still receive only two minutes");SetExpiry(expiringItem,DateTime.UtcNow.AddMilliseconds(-1));Check(Call(server,"/api/pair","POST",new{ticket=expiring},null,null).Status==401,"unapproved expired tickets remain unavailable");
   string rejected=SubmitPair(server,newCode,"Rejected iPad");server.Reject(PendingId(PendingTicket(server,rejected)));Check(Call(server,"/api/pair","POST",new{ticket=rejected},null,null).Status==401,"explicit rejection immediately invalidates its ticket");
   string stopped=SubmitPair(server,newCode,"Stopped iPad");server.Approve(PendingId(PendingTicket(server,stopped)),new CompanionGrant());server.Stop();Check(Call(server,"/api/pair","POST",new{ticket=stopped},null,null).Status==401,"stop clears approved but unclaimed tickets immediately");
  }
  root=Path.Combine(fixture,"pairing-save-failure");Directory.CreateDirectory(root);File.WriteAllText(Path.Combine(root,"runtime-data"),"block directory creation inside fixture");
  using(var server=new CompanionServer(root,(path,body,grant)=>CompanionReply.Json(200,new{ok=true}),()=>false)){
   string ticket=SubmitPair(server,OpenTestPairing(server),"Unsaved iPad");object item=PendingTicket(server,ticket);DateTime original=DateTime.UtcNow.AddSeconds(5);SetExpiry(item,original);bool rejected=false;try{server.Approve(PendingId(item),new CompanionGrant());}catch(IOException){rejected=true;}
   Check(rejected&&PendingExpiry(item)==original&&item.GetType().GetField("deviceId").GetValue(item)==null&&item.GetType().GetField("token").GetValue(item)==null,"failed approval persistence neither grants authorization nor extends ticket lifetime");Check(((System.Collections.IList)Status(server)["devices"]).Count==0&&Call(server,"/api/pair","POST",new{ticket=ticket},null,null).Status==202,"failed approval leaves only the original pending request");
  }
 }
 static string Pair(CompanionServer server,CompanionGrant grant){
  string code=OpenTestPairing(server);var initial=Call(server,"/api/pair","POST",new{code=code,name="Test iPad"},null,null);Check(initial.Status==202,"correct code creates pending request");string ticket=(string)Data(initial)["ticket"];
  Check(Call(server,"/api/pair","POST",new{ticket=ticket},null,null).Status==202,"pairing waits for explicit desktop approval");var waiting=(System.Collections.IList)Status(server)["pending"];string id=(string)((Dictionary<string,object>)waiting[0])["id"];
  server.Approve(id,grant);var paired=Call(server,"/api/pair","POST",new{ticket=ticket},null,null);Check(paired.Status==200,"desktop approval establishes session");string cookie=paired.Headers["Set-Cookie"];Check(cookie.Contains("HttpOnly; Secure; SameSite=Strict"),"session cookie uses secure flags");Check(Call(server,"/api/pair","POST",new{ticket=ticket},null,null).Status==401,"pairing ticket is single-use");return cookie.Substring(cookie.IndexOf('=')+1,64);
 }
 static System.Collections.IDictionary Buckets(CompanionServer server,string name){return (System.Collections.IDictionary)typeof(CompanionServer).GetField(name,System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(server);}
 static void ExpireRates(CompanionServer server,string name){foreach(object rate in Buckets(server,name).Values)rate.GetType().GetField("until").SetValue(rate,DateTime.UtcNow.AddSeconds(-1));}
 static bool Retry(CompanionReply reply,string code,int minimum,int maximum){string header;int seconds;return reply.Status==429&&(string)Data(reply)["error"]==code&&reply.Headers.TryGetValue("Retry-After",out header)&&int.TryParse(header,out seconds)&&seconds>=minimum&&seconds<=maximum&&Convert.ToInt32(Data(reply)["retryAfter"])==seconds;}
 static string Asset(int index){return "/api/assets/"+index.ToString("x32");}
 static CompanionServer.Device Device(CompanionServer server){return ((List<CompanionServer.Device>)typeof(CompanionServer).GetField("devices",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).GetValue(server))[0];}
 static void BudgetChecks(string fixture){
  using(var server=new CompanionServer(Path.Combine(fixture,"budgets"),(path,body,grant)=>path.StartsWith("/api/assets/")?CompanionReply.Asset(new byte[]{1,2,3},"image/png"):CompanionReply.Json(200,new{ok=true}),()=>false)){
   string cookie=Pair(server,new CompanionGrant{apps=true});bool loaded=true;for(int i=0;i<500;i++)loaded&=Call(server,Asset(i),"GET",null,cookie,null).Status==200;Check(loaded,"all 500 distinct authorized library icons fit one device window");
   bool margin=true;for(int i=500;i<600;i++)margin&=Call(server,Asset(i),"GET",null,cookie,null).Status==200;Check(margin,"icon budget includes bounded cover and shortcut headroom");
   var limited=Call(server,Asset(600),"GET",null,cookie,null);Check(Retry(limited,"rate_limited",1,60),"repeated icon loading is limited with matching header and JSON retry time");
   object deviceRate=Buckets(server,"assetRates")["device:"+Device(server).id];DateTime deadline=DateTime.UtcNow.AddSeconds(7);deviceRate.GetType().GetField("until").SetValue(deviceRate,deadline);
   limited=Call(server,Asset(601),"GET",null,cookie,null);Check(Retry(limited,"rate_limited",1,7)&&(DateTime)deviceRate.GetType().GetField("until").GetValue(deviceRate)==deadline,"retry time uses remaining window without extending it on rejection");
   for(int i=602;i<730;i++)Call(server,Asset(i),"GET",null,cookie,null);
   Check(Call(server,"/api/state","GET",null,cookie,null).Status==200,"exhausted image device and IP budgets do not consume state budget");
   bool coreLoaded=true;for(int i=1;i<180;i++)coreLoaded&=Call(server,"/api/state","GET",null,cookie,null).Status==200;Check(coreLoaded&&Retry(Call(server,"/api/state","GET",null,cookie,null),"rate_limited",1,60),"core device rate limit remains independently enforced");
   ExpireRates(server,"assetRates");Check(Call(server,Asset(1),"GET",null,cookie,null).Status==200,"image window recovers independently while core device remains limited");
   ExpireRates(server,"rates");Check(Call(server,"/api/state","GET",null,cookie,null).Status==200,"expired core rate window permits state again");
   string diagnostics=Json.Serialize(Status(server)["diagnostics"]);Check(diagnostics.Contains("\"route\":\"asset\"")&&diagnostics.Contains("\"route\":\"core\"")&&diagnostics.Contains("\"scope\":\"ip\"")&&diagnostics.Contains("\"scope\":\"device\""),"diagnostics distinguish asset/core and IP/device limit rejection categories");Check(!diagnostics.Contains(cookie)&&!diagnostics.Contains("192.168.1.21")&&!diagnostics.Contains(Asset(1))&&!diagnostics.Contains(Device(server).id),"diagnostics retain no cookie, address, asset URL or device identifier");
  }
  using(var server=new CompanionServer(Path.Combine(fixture,"bucket-isolation"),(path,body,grant)=>CompanionReply.Json(200,new{ok=true}),()=>false)){
   bool denied=true;for(int i=0;i<128;i++){var request=Request(Asset(i),"GET",null,null,null);request.RemoteAddress="10.0.0."+i;denied&=server.Dispatch(request,Origin).Status==401;}var overflow=Request(Asset(129),"GET",null,null,null);overflow.RemoteAddress="10.0.1.1";
   Check(denied&&Retry(server.Dispatch(overflow,Origin),"rate_limited",1,60)&&Buckets(server,"assetRates").Count==128,"unauthenticated asset callers have a bounded 128-entry rate table");
   Check(Call(server,"/api/state","GET",null,null,null).Status==401,"full asset rate table cannot crowd out core admission or authentication");
   string code=OpenTestPairing(server);bool pairedAttempts=true;for(int i=0;i<6;i++)pairedAttempts&=Call(server,"/api/pair","POST",new{code="invalid",name="Test"},null,null).Status==401;
   Check(pairedAttempts&&Retry(Call(server,"/api/pair","POST",new{code=code,name="Test"},null,null),"pair_limited",1,60),"pairing brute-force limit retains its independent retry deadline");
  }
 }
 static Task<CompanionReply> Background(Func<CompanionReply> action){return Task.Factory.StartNew(action,CancellationToken.None,TaskCreationOptions.LongRunning,TaskScheduler.Default);}
 static void ConcurrencyChecks(string fixture){
  string web=Path.Combine(fixture,"concurrency","companion-web");Directory.CreateDirectory(web);File.WriteAllText(Path.Combine(web,"index.html"),"<!doctype html><title>Fixture</title>");
  var assetEntered=new CountdownEvent(4);var coreEntered=new CountdownEvent(8);var releaseAssets=new ManualResetEventSlim(false);var releaseCore=new ManualResetEventSlim(false);bool blockCore=false;var running=new List<Task<CompanionReply>>();
  try{using(var server=new CompanionServer(Path.Combine(fixture,"concurrency"),(path,body,grant)=>{if(path.StartsWith("/api/assets/")){assetEntered.Signal();releaseAssets.Wait();return CompanionReply.Asset(new byte[]{1},"image/png");}if(blockCore){coreEntered.Signal();releaseCore.Wait();}return CompanionReply.Json(200,new{ok=true});},()=>false)){
   string cookie=Pair(server,new CompanionGrant{apps=true});for(int i=0;i<4;i++){int id=i;running.Add(Background(()=>Call(server,Asset(id),"GET",null,cookie,null)));}Check(assetEntered.Wait(3000),"four authorized image handlers occupy only the asset pool");
   Check(Retry(Call(server,Asset(5),"GET",null,cookie,null),"busy",1,1),"image burst returns short busy retry without reaching a fifth handler");Check(Call(server,"/api/state","GET",null,cookie,null).Status==200,"state request completes while every image slot is occupied");
   blockCore=true;for(int i=0;i<8;i++)running.Add(Background(()=>Call(server,"/api/state","GET",null,cookie,null)));Check(coreEntered.Wait(3000),"eight core handlers retain an independent bounded pool");Check(Retry(Call(server,"/api/state","GET",null,cookie,null),"busy",1,1),"core burst has its own short busy retry");
   var diagnostics=(Dictionary<string,object>)Status(server)["diagnostics"];Check(Convert.ToInt32(diagnostics["coreActive"])==8&&Convert.ToInt32(diagnostics["assetActive"])==4,"diagnostics report current independent in-flight counts");
   var startup=Background(()=>Call(server,"/","GET",null,null,null));running.Add(startup);Check(!startup.Wait(100),"startup resource waits briefly instead of rejecting an HTTP/2 burst");
   releaseAssets.Set();for(int i=0;i<4;i++)Check(running[i].Wait(3000)&&running[i].Result.Status==200,"admitted asset request completes after release");
   releaseCore.Set();Check(Task.WaitAll(running.ToArray(),3000),"all admitted core requests complete after release");Check(startup.Result.Status==200,"queued startup resource loads when a request slot becomes available");blockCore=false;Check(Call(server,"/api/state","GET",null,cookie,null).Status==200,"concurrency rejection does not leak core slots");
   diagnostics=(Dictionary<string,object>)Status(server)["diagnostics"];Check(Convert.ToInt32(diagnostics["coreActive"])==0&&Convert.ToInt32(diagnostics["assetActive"])==0,"both request pools return to zero in flight");
  }}finally{releaseAssets.Set();releaseCore.Set();if(running.Count>0)Task.WaitAll(running.ToArray(),5000);assetEntered.Dispose();coreEntered.Dispose();releaseAssets.Dispose();releaseCore.Dispose();}
 }
