 static void AppearanceChecks(string fixture){
  string root=Path.Combine(fixture,"appearance"),web=Path.Combine(root,"companion-web");Directory.CreateDirectory(web);
  foreach(string name in new[]{"lyrics-style.js","dock-lyrics.css"})File.WriteAllText(Path.Combine(root,name),"shared "+name);
  foreach(string name in new[]{"companion-scan.js","jsqr.js","companion-lyrics.js","companion-settings.js","companion-widgets.js","companion-appearance.css","manifest.webmanifest","companion-icon.png"})File.WriteAllText(Path.Combine(web,name),"companion "+name);
  int calls=0;using(var server=new CompanionServer(root,(path,body,grant)=>{calls++;return CompanionReply.Json(200,new{ok=true});},()=>false)){
   foreach(string name in new[]{"companion-scan.js","jsqr.js"}){var scan=Call(server,"/"+name,"GET",null,null,null);Check(scan.Status==200&&scan.ContentType=="application/javascript; charset=utf-8","local camera decoder has an exact public script route: "+name);}
   foreach(string name in new[]{"lyrics-style.js","dock-lyrics.css","companion-lyrics.js","companion-settings.js","companion-widgets.js","companion-appearance.css"})Check(Call(server,"/"+name,"GET",null,null,null).Status==200,"only installed appearance resource served: "+name);
   Check(Call(server,"/manifest.webmanifest","GET",null,null,null).ContentType=="application/manifest+json; charset=utf-8"&&Call(server,"/companion-icon.png","GET",null,null,null).ContentType=="image/png","public home screen manifest and icon have exact MIME types");Check(Call(server,"/other.webmanifest","GET",null,null,null).Status==404&&Call(server,"/other.png","GET",null,null,null).Status==404&&Call(server,"/manifest.webmanifest","POST",new{},null,null).Status==405,"home screen resources do not widen filenames or writes");
   Check(Call(server,"/lyrics-settings.json","GET",null,null,null).Status==404&&Call(server,"/../lyrics-style.js","GET",null,null,null).Status>=400,"shared renderer route never exposes settings or parent paths");
   string cookie=Pair(server,new CompanionGrant{music=true});string csrf=Device(server).csrf;Check(Call(server,"/api/lyrics-style","POST",new{requestId=Guid.NewGuid().ToString("N")},cookie,csrf).Status==403&&calls==0,"read-only music cannot edit lyrics style");
   server.UpdateGrant(Device(server).id,new CompanionGrant{control=true});Check(Call(server,"/api/lyrics-style","POST",new{requestId=Guid.NewGuid().ToString("N")},cookie,csrf).Status==403&&calls==0,"control without music cannot edit lyrics style");
   server.UpdateGrant(Device(server).id,new CompanionGrant{control=true,music=true});var body=new{requestId=Guid.NewGuid().ToString("N"),expectedRevision="revision",appearance=new{effect="float"}};
   Check(Call(server,"/api/lyrics-style","POST",body,cookie,null).Status==403&&calls==0,"style writes retain CSRF protection");
   Check(Call(server,"/api/lyrics-style","POST",body,cookie,csrf).Status==200&&calls==1&&Call(server,"/api/lyrics-style","POST",body,cookie,csrf).Status==200&&calls==1,"style write requires both permissions and remains deduplicated");
  }
 }
 static void ScreenRouteChecks(string fixture){
  int calls=0;bool locked=false;using(var server=new CompanionServer(Path.Combine(fixture,"screen-security"),(path,body,grant)=>{calls++;return CompanionReply.Json(200,new{ok=true});},()=>locked)){
   Check(Call(server,"/api/screen","GET",null,null,null).Status==401&&calls==0,"screen metadata requires pairing");
   string cookie=Pair(server,new CompanionGrant{pointer=true});string csrf=Device(server).csrf;
   Check(Call(server,"/api/screen","GET",null,cookie,null).Status==403&&calls==0,"pointer permission does not grant screen access");
   server.UpdateGrant(Device(server).id,new CompanionGrant{screen=true});
   Check(Call(server,"/api/screen","GET",null,cookie,null).Status==200&&calls==1,"explicit screen grant authorizes metadata");
   var offer=new{monitor=0,quality="720",offer="v=0\r\n"};
   Check(Call(server,"/api/screen/begin","POST",offer,cookie,null).Status==403&&calls==1,"screen signaling requires CSRF");
   var cross=Request("/api/screen/begin","POST",offer,cookie,csrf);cross.Origin="https://evil.example";Check(server.Dispatch(cross,Origin).Status==403&&calls==1,"foreign origin cannot open a video stream");
   Check(Call(server,"/api/screen/begin","GET",null,cookie,null).Status==403&&calls==1,"image-style GET cannot open capture");
   Check(Call(server,"/api/screen/begin","POST",offer,cookie,csrf).Status==200&&calls==2&&Device(server).commands.Count==0,"ephemeral signaling does not cache video sessions in action history");
   locked=true;Check(Call(server,"/api/screen/ping","POST",new{lease="test"},cookie,csrf).Status==423&&calls==2,"lock blocks stream heartbeats");locked=false;
   server.Revoke(Device(server).id);Check(Call(server,"/api/screen","GET",null,cookie,null).Status==401&&calls==2,"revoked viewer cannot access streaming routes");
  }
 }

}
